// One item per project due a scan: its sources, its terms by pillar (priority first), its networks and quota.
const now = Date.now();
const out = [];
for (const project of $json.data.projects || []) {
  if (project.next_scan_at && new Date(project.next_scan_at).getTime() > now) continue; // not yet
  for (const track of project.tracks || []) {
    const demand = track.demand || {};
    if (demand.accept_up_to !== null && demand.accept_up_to !== undefined && demand.accept_up_to <= 0) continue; // enough this week
    const terms = [];
    for (const pillar of track.pillars || []) for (const term of pillar.terms || []) terms.push({ pillar: pillar.pillar, ...term });
    terms.sort((a, b) => (a.priority === 'high' ? -1 : 0) - (b.priority === 'high' ? -1 : 0));
    out.push({ json: { project: project.project, track: track.track, networks: project.networks || [], sources: track.sources || [], terms, lookback_days: demand.lookback_days || 7, accept_up_to: demand.accept_up_to } });
  }
}
return out;

// RSS sources: web, blog, press, Google Trends. Each source becomes one HTTP read; the filter runs after.
const out = [];
for (const source of $json.sources) {
  if (!['WEB', 'OTHER'].includes(source.kind)) continue;
  out.push({ json: { ...$json, source } });
}
return out;

// Keep an entry when a keyword or hashtag of a pillar appears in its title or summary, within lookback_days.
// Everything read here is untrusted text: it is passed on, never executed, and Intake trims it again.
const ctx = $('Nguồn RSS').item.json;
const since = Date.now() - ctx.lookback_days * 86400000;
const hay = `${$json.title || ''} ${$json.contentSnippet || $json.content || ''}`.toLowerCase();
const when = $json.isoDate || $json.pubDate;
if (when && new Date(when).getTime() < since) return [];
const hit = ctx.terms.find((term) => hay.includes(term.text.toLowerCase().replace(/^#/, '')));
if (!hit) return [];
return [{ json: { url: $json.link, title: ($json.title || '').slice(0, 300), excerpt: ($json.contentSnippet || '').slice(0, 1000), author: ($json.creator || '').slice(0, 120), source_id: ctx.source.id, project: ctx.project, track: ctx.track, pillar: hit.pillar, keyword: hit.text, priority: hit.priority, via: 'api', published_at: when ? new Date(when).toISOString() : null } }];

// YouTube Data API search, only for projects that turned YouTube on and only for priority terms (100 searches a day are free).
const cfg = $('Config').first().json;
if (!cfg.youtubeKey || !$json.networks.includes('YOUTUBE')) return [];
return $json.terms.filter((t) => t.priority === 'high' && t.kind === 'keyword').slice(0, 3).map((term) => ({ json: { ...$json, term, url: `https://www.googleapis.com/youtube/v3/search?part=snippet&type=video&order=date&maxResults=10&q=${encodeURIComponent(term.text)}&key=${cfg.youtubeKey}` } }));

const ctx = $('YouTube theo từ khóa ưu tiên').item.json;
const since = Date.now() - ctx.lookback_days * 86400000;
const out = [];
for (const item of $json.items || []) {
  const when = item.snippet?.publishedAt;
  if (when && new Date(when).getTime() < since) continue;
  out.push({ json: { url: `https://www.youtube.com/watch?v=${item.id?.videoId}`, title: (item.snippet?.title || '').slice(0, 300), excerpt: (item.snippet?.description || '').slice(0, 1000), author: (item.snippet?.channelTitle || '').slice(0, 120), project: ctx.project, track: ctx.track, pillar: ctx.term.pillar, keyword: ctx.term.text, priority: ctx.term.priority, via: 'api', published_at: when || null } });
}
return out;

// Instagram hashtags and Threads keyword search (Meta Graph API, after app review): fill in the token and turn this node on.
// Each result becomes { url, title, excerpt, project, track, pillar, keyword, priority, via: 'api', published_at }.
return [];

// A scraping service (for Facebook public pages, TikTok): call it here and send what it returns with via: 'scrape'.
// Intake scores these one notch below whitelisted sources and never learns which service was used.
return [];

// Everything found, deduplicated by url, cut to the project's quota, in batches of 50, each signed.
const crypto = require('crypto');
const cfg = $('Config').first().json;
const seen = new Set();
const byProject = {};
for (const item of $input.all()) {
  const row = item.json;
  if (!row.url || !row.title || seen.has(row.url)) continue;
  seen.add(row.url);
  (byProject[row.project] = byProject[row.project] || []).push(row);
}
const quotas = {};
for (const ctx of $('Dự án tới giờ quét').all()) quotas[ctx.json.project] = ctx.json.accept_up_to;
const out = [];
for (const [project, rows] of Object.entries(byProject)) {
  const limit = quotas[project] === null || quotas[project] === undefined ? rows.length : quotas[project];
  const kept = rows.slice(0, limit);
  for (let i = 0; i < kept.length; i += 50) {
    const body = JSON.stringify({ items: kept.slice(i, i + 50) });
    const timestamp = String(Math.floor(Date.now() / 1000));
    const signature = crypto.createHmac('sha256', cfg.secret).update(`${timestamp}.${body}`).digest('hex');
    out.push({ json: { body, timestamp, signature, base: cfg.base } });
  }
}
return out;

// What Intake refused, for the n8n log: a reason per index. Nothing else to do; Intake keeps its own counts.
const data = $json.data || {};
if ((data.rejected || []).length) console.log('Intake rejected', JSON.stringify(data.rejected));
return [{ json: { accepted: data.accepted, duplicates: data.duplicates, rejected: (data.rejected || []).length } }];
